contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address newOwner) public {
        require(newOwner != address(0), "new owner must be non-zero to avoid revert");

        c.transferOwnership(newOwner); if (__ESBMC_reverted()) return;
        address ownerAfterTransfer = c.owner(); if (__ESBMC_reverted()) return;

        c.renounceOwnership(); if (__ESBMC_reverted()) return;
        address ownerAfterRenounce = c.owner(); if (__ESBMC_reverted()) return;

        assert(ownerAfterTransfer == newOwner && ownerAfterRenounce == address(0));
    }
}

